std::vector<double> Matrix::SumPerColumn() const {
    struct StridedIter {
        const double* p;
        std::ptrdiff_t stride;
        double operator*() const { return *p; }
        StridedIter& operator++() { p += stride; return *this; }
        bool operator!=(const StridedIter& o) const { return p != o.p; }
    };
    const std::size_t rows = rows_;
    const std::size_t cols = cols_;
    std::vector<double> result(cols);
    std::vector<std::size_t> indices(cols);
    std::iota(indices.begin(), indices.end(), std::size_t{0});
    std::transform(indices.begin(), indices.end(), result.begin(),
                   [this, rows, cols](std::size_t c) {
                       StridedIter it{data_.data() + c,
                                      static_cast<std::ptrdiff_t>(cols)};
                       StridedIter end{data_.data() + rows * cols, 0};
                       return std::accumulate(it, end, 0.0);
                   });
    return result;
}

