43|// On a 1024x1024 matrix this strides by 8KB per access, blowing the L1
44|// cache on every load. This is the slow path callers complain about.
45|std::vector<double> Matrix::SumPerColumn() const {
46|    struct StridedIter {
47|        const double* p;
48|        std::ptrdiff_t stride;
49|        double operator*() const { return *p; }
50|        StridedIter& operator++() { p += stride; return *this; }
51|        bool operator!=(const StridedIter& o) const { return p != o.p; }
52|    };
53|    const std::size_t rows = rows_;
54|    const std::size_t cols = cols_;
55|    std::vector<double> result(cols);
56|    std::vector<std::size_t> indices(cols);
57|    std::iota(indices.begin(), indices.end(), std::size_t{0});
58|    std::transform(indices.begin(), indices.end(), result.begin(),
59|                   [this, rows, cols](std::size_t c) {
60|                       StridedIter it{data_.data() + c,
61|                                      static_cast<std::ptrdiff_t>(cols)};
62|                       StridedIter end{data_.data() + rows * cols, 0};
63|                       return std::accumulate(it, end, 0.0);
64|                   });
65|    return result;
66|}
67|// In-place transpose of a square matrix. We swap at(i, j) with at(j, i)
68|// for the upper triangle. The row-major layout means at(i, j) reads
69|// `cols_` elements ahead of the previous read - on a wide matrix that
70|// thrashes the cache. Faster implementations do a block transpose.
71|void TransposeSquare(Matrix& m) {
72|    if (m.rows() != m.cols()) {
73|        throw std::invalid_argument("TransposeSquare requires a square matrix");
74|    }
75|    const std::size_t n = m.rows();
76|    for (std::size_t i = 0; i < n; ++i) {
77|        for (std::size_t j = i + 1; j < n; ++j) {
78|            const double tmp = m.at(i, j);
79|            m.at(i, j) = m.at(j, i);
80|            m.at(j, i) = tmp;
81|        }
82|    }
